function translateDOM(root){const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('[data-user-content]'))continue;node.nodeValue=translateText(node.nodeValue)}root.querySelectorAll('[aria-label],[placeholder],[title]').forEach(el=>{for(const a of ['aria-label','placeholder','title'])if(el.hasAttribute(a))el.setAttribute(a,translateText(el.getAttribute(a)))})}
const today=()=>iso(new Date());
function iso(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function addDays(value,n){const d=new Date(`${value}T12:00:00`);d.setDate(d.getDate()+n);return iso(d)}
function uuid(){return crypto.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(36).slice(2)}`}
function starter(){const year=new Date().getFullYear();return{semester:{name:'Fall semester',start:`${year}-10-01`,end:`${year+1}-03-31`,weekGoal:12},courses:[],tasks:[],events:[],series:[],exceptions:[],blocks:[],notes:[],resources:[],sessions:[]}}
function migrate(){try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&raw.semester){for(const e of raw.events||[])e.type=({'Prüfung':'Exam','Abgabe':'Assignment','Termin':'Personal event','Vorlesung':'Lecture'}[e.type]||e.type);for(const s of raw.series||[])s.type=({'Vorlesung':'Lecture','Übung':'Tutorial','Sprechstunde':'Office hours','Sonstiges':'Other'}[s.type]||s.type);return raw}const old=JSON.parse(localStorage.getItem('studyhub-data-v1'));if(old){const d=starter();d.courses=old.courses.map((c,i)=>({...c,color:COLORS[i%COLORS.length]}));d.tasks=old.tasks;d.events=old.events.map(e=>({...e,type:({'Prüfung':'Exam','Abgabe':'Assignment','Termin':'Personal event'}[e.type]||e.type),plan:e.plan||[]}));d.series=old.classes.map(c=>({id:c.id,title:d.courses.find(x=>x.id===c.courseId)?.name||'Class',courseId:c.courseId,day:['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'].indexOf(c.day),start:c.start,end:c.end,room:c.room||'',lecturer:'',type:'Lecture',from:d.semester.start,to:d.semester.end}));localStorage.setItem(KEY,JSON.stringify(d));return d;}}catch(e){console.warn('UniFlow data could not be read',e)}return starter()}
let db=migrate(), page='home', selectedCourse=null, calendarDate=new Date(), calendarMode='month', timer={running:false,remaining:25*60,kind:'study',started:0,interval:null},timerSettings={study:25,break:5};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const course=id=>db.courses.find(c=>c.id===id), courseLabel=id=>course(id)?.name||'No course';
const pretty=(v,opt={day:'numeric',month:'short'})=>v?new Date(`${v}T12:00:00`).toLocaleDateString('en-US',opt):'—';
const options=(items,selected,blank='No course')=>`<option value="">${blank}</option>`+items.map(x=>`<option data-user-content value="${esc(x.id)}" ${x.id===selected?'selected':''}>${esc(x.name||x.title)}</option>`).join('');
function toast(s){const t=document.querySelector('#toast');t.textContent=translateText(s);t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2600)}
function setPage(p){page=p;if(p!=='course')selectedCourse=null;document.querySelector('#mobile-more')?.setAttribute('hidden','');document.querySelector('[data-action="more-toggle"]')?.setAttribute('aria-expanded','false');render()}
function header(k,title,sub,action=''){return `<div class="page-head"><div><div class="kicker">${k}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function btn(label,act,kind='',cls='primary'){return `<button class="btn ${cls}" data-action="${act}" ${kind?`data-kind="${kind}"`:''}>${label}</button>`}
function weekStart(d=new Date()){const x=new Date(d);x.setHours(12,0,0,0);x.setDate(x.getDate()-(x.getDay()+6)%7);return x}
let semesterView='week',weekOffset=0;
function field(label,name,type='text',value='',full=false,required=false){return `<label class="field ${full?'full':''}">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''}></label>`}
function selectField(label,name,html,full=false){return `<label class="field ${full?'full':''}">${label}<select name="${name}">${html}</select></label>`}
function textarea(label,name,value='',full=true){return `<label class="field ${full?'full':''}">${label}<textarea name="${name}" rows="3">${esc(value)}</textarea></label>`}
let modalContext={};
function exportBackup(){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`study-hub-backup-${today()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Backup exported')}
function timerStart(){if(timer.running)return;if(timer.kind==='study'){const selected=db.courses.find(c=>c.id===db.focusCourseId);if(db.courses.length&&!selected){toast('Choose a course before starting a study session.');return}timer.courseId=selected?.id||null}timer.running=true;timer.started=Date.now()-(timerSettings[timer.kind]*60-timer.remaining)*1000;timer.interval=setInterval(()=>{timer.remaining=Math.max(0,timerSettings[timer.kind]*60-Math.floor((Date.now()-timer.started)/1000));const el=document.querySelector('#timer-display');if(el)el.textContent=`${String(Math.floor(timer.remaining/60)).padStart(2,'0')}:${String(timer.remaining%60).padStart(2,'0')}`;if(!timer.remaining){clearInterval(timer.interval);timer.running=false;if(timer.kind==='study'){db.sessions.push({date:today(),minutes:timerSettings.study,courseId:timer.courseId||null});timer.courseId=null;save();timer.kind='break';toast('Focus session complete. Time for a break!')}else{timer.kind='study';toast('Break over. Ready to focus?')}timer.remaining=timerSettings[timer.kind]*60;render()}},250)}
function timetableState(){return {semester:JSON.parse(JSON.stringify(db.semester)),series:JSON.parse(JSON.stringify(db.series)),exceptions:JSON.parse(JSON.stringify(db.exceptions)),blocks:JSON.parse(JSON.stringify(db.blocks))}}
let lastTimetableState=JSON.stringify(timetableState()),undoingTimetable=false;
function subjectSelect(selected='',required=false){return `<label class="field">Course<select name="courseId" ${required?'required':''}>${options(db.courses,selected,'Select a course')}</select></label>`}
function weekdayOptions(selected){const chosen=Number(selected),items=DAY_NAMES.slice(0,5).map((name,i)=>`<option value="${i}" ${chosen===i?'selected':''}>${name}</option>`);if(chosen>=5&&chosen<7)items.push(`<option value="${chosen}" selected>${DAY_NAMES[chosen]} (existing)</option>`);return items.join('')}
function nextClassDate(from,day){let d=from>today()?from:today();while(((new Date(`${d}T12:00:00`).getDay()+6)%7)!==Number(day))d=addDays(d,1);return d}
function pageHeader(label,title,subtitle,action=''){return header(label,title,subtitle,action)}
function eventCard(e){const c=course(e.courseId),title=e.occurrence&&c?.name||e.title||c?.name||e.subjectName||'Class',span=e.endDate&&e.endDate!==e.date?`${pretty(e.date,{month:'short',day:'numeric'})} – ${pretty(e.endDate,{month:'short',day:'numeric',year:'numeric'})}`:'';return `<div class="event-card" data-action="occurrence" data-id="${e.id}" role="button" tabindex="0"><span class="datebox"><b>${pretty(e.date,{day:'numeric'})}</b><small>${pretty(e.date,{month:'short'})}</small></span><div class="event-info"><strong data-user-content>${esc(title)}</strong><small data-user-content>${esc(span||e.time||e.start||(e.type==='Task'?'Due date':''))} · ${esc(e.location||e.room||e.type||'Class')}</small></div><i class="course-color" style="--c:${c?.color||'#8975d6'}"></i></div>`}
function examsPage(){const exams=db.events.filter(e=>e.type==='Exam').sort((a,b)=>a.date.localeCompare(b.date));return `${pageHeader('YOUR DATES','Exams','Exam dates, locations, and countdowns.',btn('＋ Add exam','new','exam'))}<section class="surface">${exams.map(e=>{const days=Math.ceil((new Date(e.date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000);return `<article class="exam-row"><div class="exam-date"><b>${pretty(e.date,{day:'numeric'})}</b><span>${pretty(e.date,{month:'short',year:'numeric'})}</span></div><div class="exam-info"><strong data-user-content>${esc(e.title)}</strong><small>${esc(course(e.courseId)?.name||e.subjectName||'No course')} · ${esc(e.time||'Time not set')}${e.location?' · '+esc(e.location):''}</small>${e.description?`<p>${esc(e.description)}</p>`:''}</div><span class="countdown">${days<0?'Past':days===0?'Today':`${days} days`}</span><button class="link" data-action="edit" data-kind="exam" data-id="${e.id}">Edit</button><button class="link danger" data-action="delete" data-kind="exam" data-id="${e.id}">Delete</button></article>`}).join('')||'<div class="empty">No exams added yet. Add an exam to see its countdown here.</div>'}</section>`}
function semesterPage(){const actions=semesterView==='semester'?`<div class="page-head-actions">${btn('Today','week-now','','soft')}${btn('＋ Class','new','series')}</div>`:btn('＋ Class','new','series');return `${pageHeader('YOUR SEMESTER','Timetable','Weekly classes appear only within your semester dates.',actions)}<section class="surface semester-bar"><label>Semester name<input data-sem="name" value="${esc(db.semester.name)}"></label><label>Start date<input type="date" data-sem="start" value="${db.semester.start}"></label><label>End date<input type="date" data-sem="end" value="${db.semester.end}"></label><label>Weekly study target<input type="number" min="1" max="80" data-sem="weekGoal" value="${db.semester.weekGoal}"></label><button class="btn primary" data-action="semester-save">Save</button></section><div class="view-tabs"><button class="${semesterView==='week'?'on':''}" data-action="semester-view" data-value="week">Week view</button><button class="${semesterView==='semester'?'on':''}" data-action="semester-view" data-value="semester">Semester overview</button></div>${semesterView==='week'?weekGrid():semesterGrid()}`}
function focusPage(){const m=Math.floor(timer.remaining/60),s=timer.remaining%60,mins=db.sessions.filter(x=>x.date>=addDays(today(),-6)).reduce((n,x)=>n+x.minutes,0),chosen=course(db.focusCourseId);return `${pageHeader('OPTIONAL TOOL','Focus Room','Choose a course to record what you study, then start a focus block.')}<div class="focus-layout"><section class="timer-card"><span class="kicker">${timer.kind==='study'?'FOCUS':'BREAK'}</span><div class="focus-course-field"><label for="focus-course">What are you studying?</label><select id="focus-course" ${timer.running?'disabled':''}><option value="">${db.courses.length?'Choose a course':'No courses yet'}</option>${db.courses.map(c=>`<option value="${esc(c.id)}" ${c.id===chosen?.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${db.courses.length?'':`<button class="link" data-page="courses">Add a course to track sessions</button>`}</div><div class="timer-display" id="timer-display">${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}</div><div class="timer-actions">${btn(timer.running?'Pause':timer.remaining<timerSettings[timer.kind]*60?'Resume':'Start',timer.running?'timer-pause':'timer-start')}${btn('Reset','timer-reset','','soft')}</div><div class="timer-config"><label>Study <input id="study-min" type="number" min="1" max="180" value="${timerSettings.study}"> min</label><label>Break <input id="break-min" type="number" min="1" max="60" value="${timerSettings.break}"> min</label><button class="link" data-action="timer-settings">Apply</button></div></section><section class="surface"><div class="surface-head"><div><h2>This week</h2><p>Recorded focus time</p></div></div><div class="big-stat">${(mins/60).toFixed(1)} <small>hours</small></div><div class="progress-track"><i style="width:${Math.min(100,mins/(db.semester.weekGoal*60)*100)}%"></i></div><p class="muted">Weekly target: ${db.semester.weekGoal} hours</p>${db.sessions.slice(-5).reverse().map(x=>`<div class="mini-row">${pretty(x.date,{weekday:'short',day:'numeric',month:'short'})}<small>${course(x.courseId)?.name||'Unassigned'} · ${x.minutes} minutes</small></div>`).join('')||'<div class="empty">Completed focus sessions will appear here.</div>'}</section></div>`}
function statsPage(){const days=Array.from({length:7},(_,i)=>addDays(today(),i-6)),max=Math.max(1,...days.map(d=>db.sessions.filter(s=>s.date===d).reduce((a,b)=>a+b.minutes,0))),byCourse=Object.values(db.sessions.reduce((acc,x)=>{const id=x.courseId||'unassigned',name=course(x.courseId)?.name||'Unassigned';acc[id]||={name,minutes:0,sessions:0};acc[id].minutes+=Number(x.minutes)||0;acc[id].sessions++;return acc},{})).sort((a,b)=>b.minutes-a.minutes);return `${pageHeader('YOUR OVERVIEW','My Progress','A simple view of your recorded study time.')}<div class="stats"><article class="stat"><span>Study time recorded</span><strong>${Math.round(db.sessions.reduce((a,s)=>a+s.minutes,0)/60)}<small> hrs</small></strong><small>All completed sessions</small></article><article class="stat"><span>Focus sessions</span><strong>${db.sessions.length}</strong><small>Recorded on this device</small></article><article class="stat"><span>Upcoming exams</span><strong>${db.events.filter(e=>e.type==='Exam'&&e.date>=today()).length}</strong><small>Stored exam dates</small></article><article class="stat"><span>Courses</span><strong>${db.courses.length}</strong><small>This semester</small></article></div><section class="surface chart"><div class="surface-head"><div><h2>Last 7 days</h2><p>Minutes from completed focus sessions</p></div></div><div class="bars">${days.map(d=>{const n=db.sessions.filter(s=>s.date===d).reduce((a,b)=>a+b.minutes,0);return `<div><span style="height:${Math.max(4,n/max*100)}%" title="${n} minutes"></span><small>${pretty(d,{weekday:'short'})}</small><b>${n||''}</b></div>`}).join('')}</div></section><section class="surface course-study"><div class="surface-head"><div><h2>Study time by course</h2><p>Recorded focus sessions, grouped by course</p></div></div>${byCourse.map(x=>`<div class="mini-row"><strong>${esc(x.name)}</strong><small>${(x.minutes/60).toFixed(1)} hours · ${x.sessions} sessions</small></div>`).join('')||'<div class="empty">Choose a course in Focus Room to see your study time here.</div>'}</section>`}
function timeMinutes(value){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(value||''))return NaN;const [h,m]=value.split(':').map(Number);return h*60+m}
function timeToY(value){return timeMinutes(value)-TIMELINE_START}
function classOccurrences(start,end){if(!start||!end||end<db.semester.start||start>db.semester.end)return[];const from=new Date(`${addDays(start,-7)}T12:00:00`),to=new Date(`${addDays(end,7)}T12:00:00`),semStart=new Date(`${db.semester.start}T12:00:00`),semEnd=new Date(`${db.semester.end}T12:00:00`),dates=new Set(),out=[];if(from<semStart)from.setTime(semStart.getTime());if(to>semEnd)to.setTime(semEnd.getTime());for(let d=new Date(from);d<=to;d.setDate(d.getDate()+1))dates.add(iso(d));db.exceptions.filter(x=>x.newDate>=start&&x.newDate<=end).forEach(x=>dates.add(x.date));for(const originalDate of [...dates].sort()){const weekday=(new Date(`${originalDate}T12:00:00`).getDay()+6)%7;if(db.blocks.some(b=>originalDate>=b.from&&originalDate<=b.to))continue;for(const s of db.series.filter(x=>Number(x.day)===weekday&&originalDate>=x.from&&originalDate<=x.to)){const ex=db.exceptions.find(x=>x.seriesId===s.id&&x.date===originalDate);if(ex?.cancelled)continue;const actualDate=ex?.newDate||originalDate;if(actualDate<start||actualDate>end)continue;const item={...s,...ex,date:actualDate,originalDate,occurrence:true,id:`${s.id}@${originalDate}`};if(timeMinutes(item.start)>=timeMinutes(item.end))continue;out.push(item)}}out.sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start));return out}
function occurrences(start,end){return classOccurrences(start,end)}
function semesterProgress(){const s=new Date(db.semester.start+'T12:00:00'),e=new Date(db.semester.end+'T12:00:00'),n=new Date(today()+'T12:00:00');return Math.max(0,Math.min(100,Math.round((n-s)/(e-s)*100)))}
function isBerlinCalendarEvent(e){return typeof e.id==='string'&&(e.id.startsWith('berlin-holiday-')||e.id.startsWith('berlin-break-'))}function calendarItems(start,end){return db.events.filter(e=>(db.showBerlinDates!==false||!isBerlinCalendarEvent(e))&&e.date<=end&&(e.endDate||e.date)>=start).map(e=>({...e,occurrence:false})).sort((a,b)=>(a.date+(a.time||'')).localeCompare(b.date+(b.time||'')))}
function weekGrid(){const monday=weekStart(new Date(`${addDays(today(),weekOffset*7)}T12:00:00`)),dates=Array.from({length:5},(_,i)=>iso(new Date(monday.getFullYear(),monday.getMonth(),monday.getDate()+i))),all=classOccurrences(dates[0],dates.at(-1)),hours=Array.from({length:11},(_,i)=>`${String(i+8).padStart(2,'0')}:00`);const dayColumn=d=>{const items=all.filter(x=>x.date===d).map(x=>({...x,sm:timeMinutes(x.start),em:timeMinutes(x.end)})).filter(x=>Number.isFinite(x.sm)&&Number.isFinite(x.em)&&x.em>x.sm&&x.em>TIMELINE_START&&x.sm<TIMELINE_END);const placed=[];for(const item of items){let lane=0;while(placed.some(p=>p.lane===lane&&item.sm<p.em&&p.sm<item.em))lane++;item.lane=lane;placed.push(item)}const lanes=Math.max(1,...items.map(x=>x.lane+1));return `<div class="time-day ${d===today()?'today':''}" data-date="${d}" role="presentation">${items.map(e=>{const clippedStart=Math.max(TIMELINE_START,e.sm),clippedEnd=Math.min(TIMELINE_END,e.em),top=timeToY(`${String(Math.floor(clippedStart/60)).padStart(2,'0')}:${String(clippedStart%60).padStart(2,'0')}`),height=clippedEnd-clippedStart;return `<button class="time-event" style="--top:${top}px;--height:${height}px;--left:${e.lane/lanes*100}%;--width:${100/lanes}%;--event-color:${course(e.courseId)?.color||'#7965c7'}" data-action="occurrence" data-id="${e.id}" title="${esc(course(e.courseId)?.name||e.title||e.subjectName||'Class')} · ${esc(e.type||'Class')} · ${e.start}–${e.end}${e.room?' · '+esc(e.room):''}"><strong>${esc(course(e.courseId)?.name||e.title||e.subjectName||'Class')}</strong><small>${esc(e.type||'Class')} · ${e.start}–${e.end}</small>${e.room?`<small class="time-room">${esc(e.room)}</small>`:''}</button>`}).join('')}</div>`};return `<div class="calendar-nav"><button data-action="week-prev" aria-label="Previous week">←</button><strong>${pretty(dates[0])} – ${pretty(dates.at(-1),{day:'numeric',month:'long',year:'numeric'})}</strong><button data-action="week-next" aria-label="Next week">→</button><button class="btn soft today-jump" data-action="week-now">Today</button><button class="undo-timetable" data-action="undo-timetable" aria-label="Undo last timetable change" title="Undo last timetable change" ${db.undoTimetable?'':'disabled'}>↶</button></div><div class="week-scroll"><div class="time-grid"><div class="time-head time-corner">Time</div>${dates.map(d=>`<div class="time-head ${d===today()?'today':''}">${pretty(d,{weekday:'short',month:'short',day:'numeric'})}</div>`).join('')}<div class="time-axis">${hours.map(h=>`<span style="top:${timeToY(h)+(h==='08:00'?9:0)}px">${h}</span>`).join('')}</div>${dates.map(dayColumn).join('')}</div></div><div class="surface section-gap"><div class="surface-head"><div><h2>Recurring classes</h2><p>${db.series.length} series · within semester dates</p></div></div>${db.series.map(s=>`<div class="series-row"><span class="series-dot" style="--course:${course(s.courseId)?.color||'#8975d6'}"></span><div><strong>${esc(course(s.courseId)?.name||s.title||s.subjectName||'Class')}</strong><small>${DAY_NAMES[s.day]} · ${esc(s.type||'Class')} · ${s.start}–${s.end} · ${esc(s.room||'Room not set')} · ${pretty(s.from)}–${pretty(s.to)}</small></div><button class="icon-btn" data-action="edit" data-kind="series" data-id="${s.id}">Edit</button><button class="icon-btn danger" data-action="delete" data-kind="series" data-id="${s.id}">Delete</button></div>`).join('')||'<div class="empty">No recurring classes yet. Add a class above.</div>'}${db.blocks.map(b=>`<div class="series-row"><span class="series-dot block-dot"></span><div><strong>${esc(b.name)}</strong><small>Break · ${pretty(b.from)}–${pretty(b.to)}</small></div><button class="icon-btn danger" data-action="delete" data-kind="block" data-id="${b.id}">Delete</button></div>`).join('')}</div>`}
function dashboard(){const todayClasses=classOccurrences(today(),today()),todayEvents=db.events.filter(e=>e.date<=today()&&(e.endDate||e.date)>=today()),todayItems=[...todayClasses,...todayEvents].sort((a,b)=>(a.time||a.start||'').localeCompare(b.time||b.start||'')),exams=db.events.filter(e=>e.type==='Exam'&&e.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)),upcoming=db.events.filter(e=>e.date>=today()&&e.type!=='Exam').sort((a,b)=>a.date.localeCompare(b.date)).slice(0,4),exam=exams[0],mins=db.sessions.filter(x=>x.date>=addDays(today(),-6)).reduce((n,x)=>n+x.minutes,0),greet=new Date().getHours()<12?'Good morning':new Date().getHours()<18?'Good afternoon':'Good evening';return `${pageHeader('YOUR CAMPUS',`${greet}.`,'Your day, classes, and important dates in one calm view.')}<section class="hero"><div><span class="hero-label">${esc(db.semester.name)}</span><h2>Make room<br>for your next win.</h2><p>${pretty(today(),{weekday:'long',day:'numeric',month:'long'})} · ${todayItems.length} events today</p></div><div class="hero-stat"><span>SEMESTER PROGRESS</span><strong>${semesterProgress()}%</strong><div class="progress-track"><i style="width:${semesterProgress()}%"></i></div></div></section><div class="stats"><article class="stat"><span>Courses</span><strong>${db.courses.length}</strong><small>This semester</small></article><article class="stat"><span>Upcoming exams</span><strong>${exams.length}</strong><small>${exam?`${Math.max(0,Math.ceil((new Date(exam.date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000))} days to next exam`:'No exams scheduled'}</small></article><article class="stat"><span>Study time this week</span><strong>${(mins/60).toFixed(1)}<small> hrs</small></strong><small>Recorded focus sessions</small></article><article class="stat"><span>Semester progress</span><strong>${semesterProgress()}%</strong><small>${pretty(db.semester.start)} – ${pretty(db.semester.end,{day:'numeric',month:'short'})}</small></article></div><div class="quick-actions">${btn('＋ Add class','new','series','soft')}${btn('＋ Add event','new','event','soft')}${exam?`<div class="exam-chip"><span>NEXT EXAM</span><strong>${esc(exam.title)}</strong><b>${Math.max(0,Math.ceil((new Date(exam.date+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000))} days</b></div>`:''}</div><div class="columns"><section class="surface"><div class="surface-head"><div><h2>Today’s schedule</h2><p>Classes and events for today</p></div><button class="link" data-page="semester">Open timetable →</button></div>${todayItems.map(eventCard).join('')||`<div class="empty">Nothing scheduled today. <button class="link" data-page="semester">Open timetable</button></div>`}</section><section class="surface"><div class="surface-head"><div><h2>Coming up</h2><p>Exams and personal dates</p></div><button class="link" data-page="calendar">Open calendar →</button></div>${exams.slice(0,2).map(eventCard).join('')}${upcoming.map(eventCard).join('')}${exams.length||upcoming.length?'':'<div class="empty">No upcoming dates. Add an event to keep it on your radar.</div>'}</section></div>`}
function calendarTools(){const label=db.showBerlinDates===false?'Show holidays & breaks':'Hide holidays & breaks';return `<div class="calendar-import">${btn(label,'toggle-holidays','','soft')}</div>`}function calendarPage(){const y=calendarDate.getFullYear(),m=calendarDate.getMonth(),nav=`<div class="calendar-controls"><div class="view-tabs"><button data-action="calendar-mode" data-value="month" class="${calendarMode==='month'?'on':''}">Month</button><button data-action="calendar-mode" data-value="week" class="${calendarMode==='week'?'on':''}">Week</button><button data-action="calendar-mode" data-value="day" class="${calendarMode==='day'?'on':''}">Day</button></div><div class="calendar-nav"><button data-action="cal-prev">←</button><strong>DATE_RANGE</strong><button data-action="cal-next">→</button><button class="btn soft today-jump" data-action="cal-today">Today</button></div></div>`;if(calendarMode==='month'){const first=new Date(y,m,1),offset=(first.getDay()+6)%7,start=iso(new Date(y,m,1-offset)),end=addDays(start,41),items=calendarItems(start,end),range=new Date(y,m,1).toLocaleDateString('en-US',{month:'long',year:'numeric'});return `${pageHeader('YOUR DATES','Calendar','One-off exams, deadlines, and personal events.',btn('＋ Add event','new','event'))}${calendarTools()}${nav.replace('DATE_RANGE',range)}<div class="month-grid">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="weekday">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{const d=addDays(start,i),dt=new Date(d+'T12:00:00'),dayItems=items.filter(e=>e.date<=d&&(e.endDate||e.date)>=d);return `<div class="month-cell ${dt.getMonth()===m?'':'faded'} ${d===today()?'is-today':''}"><b>${dt.getDate()}</b>${dayItems.slice(0,3).map(e=>`<button class="month-event" data-action="occurrence" data-id="${e.id}">${esc(e.title||'Event')}</button>`).join('')}${dayItems.length>3?`<small>+${dayItems.length-3} more</small>`:''}</div>`}).join('')}</div>`}const base=calendarMode==='week'?iso(weekStart(calendarDate)):iso(calendarDate),dates=calendarMode==='week'?Array.from({length:7},(_,i)=>addDays(base,i)):[base],items=calendarItems(dates[0],dates.at(-1)),range=`${pretty(base,{day:'numeric',month:'long',year:'numeric'})}${dates.length>1?' – '+pretty(dates.at(-1)):''}`;return `${pageHeader('YOUR DATES','Calendar','One-off exams, deadlines, and personal events.',btn('＋ Add event','new','event'))}${calendarTools()}${nav.replace('DATE_RANGE',range)}<section class="surface">${items.map(eventCard).join('')||'<div class="empty">No events in this view. Add an event to put it on your calendar.</div>'}</section>`}
function render(){const names={home:'Dashboard',courses:'Courses',semester:'Timetable',calendar:'Calendar',exams:'Exams',notes:'Notes',focus:'Focus Room',stats:'My Progress',settings:'Data & backup'};const current=page==='course'?'courses':page;document.querySelector('#page-title').textContent=names[page]||'Dashboard';document.querySelector('#nav-progress').textContent=`${semesterProgress()}%`;document.querySelector('#semester-name').textContent=db.semester.name;document.querySelectorAll('.mobile-nav [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===current));document.querySelectorAll('.nav-link').forEach(x=>x.classList.toggle('active',x.dataset.page===current));document.querySelector('#view').innerHTML=({home:dashboard,courses:coursesPage,semester:semesterPage,calendar:calendarPage,exams:examsPage,focus:focusPage,stats:statsPage,settings:settingsPage})[page]?.()||dashboard();translateDOM(document.querySelector('#view'));document.querySelector('#date-label').textContent=new Date().toLocaleDateString('en-US',{weekday:'long',day:'numeric',month:'long'})}
function modal(kind,id){const map={course:db.courses,event:db.events,exam:db.events,series:db.series,block:db.blocks,single:db.series};let item=id?map[kind]?.find(x=>x.id===id):null;if(kind==='single'){const [sid,date]=id.split('@'),series=db.series.find(x=>x.id===sid),ex=db.exceptions.find(x=>x.seriesId===sid&&x.date===date);if(!series)return;item={...series,...ex,id,seriesId:sid,originalDate:date,newDate:ex?.newDate||date}}modalContext={kind,id,item};const selected=item?.courseId||(page==='course'?selectedCourse:'');let title='',html='';if(kind==='single'){title='Edit this occurrence';html=field('Date','newDate','date',item.newDate,'',true)+field('Start time','start','time',item.start,'',true)+field('End time','end','time',item.end,'',true)+field('Room','room','text',item.room||'')+`<p class="form-hint full">Only this date will change. Other weekly classes stay as they are.</p>`}if(kind==='course'){title=id?'Edit course':'Add course';html=field('Course name','name','text',item?.name||'','',true)+field('Course color','color','color',item?.color||COLORS[(db.courses.findIndex(c=>c.id===id)>=0?db.courses.findIndex(c=>c.id===id):db.courses.length)%COLORS.length])}if(kind==='event'||kind==='exam'){title=id?'Edit event':kind==='exam'?'Add exam':'Add event';const type=kind==='exam'?'Exam':item?.type||'Personal event';html=field('Title','title','text',item?.title||'','',true)+(kind==='event'?selectField('Type','type',['Assignment','Exam','Personal event','Other'].map(x=>`<option ${type===x?'selected':''}>${x}</option>`).join('')):`<input type="hidden" name="type" value="Exam">`)+subjectSelect(selected)+field('Date','date','date',item?.date||today(),' ',true)+field('Through (optional)','endDate','date',item?.endDate||'')+field('Start time','time','time',item?.time||'')+field('End time','endTime','time',item?.endTime||'')+field('Location','location','text',item?.location||'')+textarea('Description','description',item?.description||'')}if(kind==='series'){title=id?'Edit recurring class':'Add recurring class';html=subjectSelect(selected,true)+selectField('Weekday','day',weekdayOptions(item?.day))+selectField('Class type','type',['Lecture','Tutorial','Exercise','Seminar','Lab','Office hours','Other'].map(x=>`<option ${item?.type===x?'selected':''}>${x}</option>`).join(''))+field('Start time','start','time',item?.start||slotDraft?.start||'09:00','',true)+field('End time','end','time',item?.end||slotDraft?.end||'10:00','',true)+field('Room','room','text',item?.room||'')+field('Repeat from','from','date',item?.from||db.semester.start,'',true)+field('Repeat through','to','date',item?.to||db.semester.end,'',true)+(slotDraft?`<input type="hidden" name="day" value="${slotDraft.day}">`: '')}if(kind==='block'){title='Add break period';html=field('Name','name','text','','',true)+field('From','from','date',db.semester.start,'',true)+field('Through','to','date',db.semester.start,'',true)}document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-fields').innerHTML=html;document.querySelector('.modal-delete')?.remove();if(id&&kind!=='single'){const b=document.createElement('button');b.type='button';b.className='btn danger-btn modal-delete';b.textContent='Delete';b.dataset.action='delete';b.dataset.kind=kind;b.dataset.id=id;document.querySelector('.dialog-actions').prepend(b)}translateDOM(document.querySelector('#dialog'));document.querySelector('#dialog').showModal()}
function submitModal(ev){ev.preventDefault();const d=Object.fromEntries(new FormData(ev.currentTarget)),{kind,id,item}=modalContext,put=(arr,obj)=>{if(id){const index=arr.findIndex(x=>x.id===id);if(index>=0)arr[index]=obj}else arr.push(obj)};if(kind==='single'){const start=timeMinutes(d.start),end=timeMinutes(d.end);if(!d.newDate||d.newDate<db.semester.start||d.newDate>db.semester.end)return toast('Choose a date within the semester.');if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return toast('End time must be after the start time.');const existing=db.exceptions.find(x=>x.seriesId===item.seriesId&&x.date===item.originalDate),record={...(existing||{}),seriesId:item.seriesId,date:item.originalDate,newDate:d.newDate,start:d.start,end:d.end,room:d.room||'',cancelled:false};if(existing)Object.assign(existing,record);else db.exceptions.push(record)}if(kind==='course'){if(!d.name.trim())return toast('Enter a course name.');if(db.courses.some(c=>c.id!==id&&c.code&&d.code&&c.code.toLowerCase()===d.code.toLowerCase()))return toast('This course code is already in use.');put(db.courses,{...item,...d,id:id||uuid()})}if(kind==='event'||kind==='exam'){if(!d.title.trim()||!d.date)return toast('Enter a title and date.');if(d.endDate&&d.endDate<d.date)return toast('The end date must be on or after the start date.');if(!d.endDate)delete d.endDate;if(d.time&&!Number.isFinite(timeMinutes(d.time))||d.endTime&&!Number.isFinite(timeMinutes(d.endTime)))return toast('Enter a valid time.');if(d.time&&d.endTime&&d.endTime<=d.time)return toast('End time must be after the start time.');d.type=kind==='exam'?'Exam':d.type;put(db.events,{...item,...d,id:id||uuid()})}if(kind==='series'){const selectedCourse=course(d.courseId);if(!selectedCourse)return toast('Choose a course for this class.');d.title=selectedCourse.name;const start=timeMinutes(d.start),end=timeMinutes(d.end);if(!Number.isFinite(start)||!Number.isFinite(end)||end<=start)return toast('Enter valid times and make sure the end is after the start.');if(d.from<db.semester.start||d.to>db.semester.end||d.to<d.from)return toast('Choose dates within the configured semester.');d.day=Number(d.day);put(db.series,{...item,...d,id:id||uuid()});const first=nextClassDate(d.from,d.day);if(first<=d.to)weekOffset=Math.floor((weekStart(new Date(first+'T12:00:00'))-weekStart(new Date(today()+'T12:00:00')))/604800000)}if(kind==='block'){if(!d.name.trim()||d.from<db.semester.start||d.to>db.semester.end||d.to<d.from)return toast('Choose a valid date range within the semester.');put(db.blocks,{...item,...d,id:id||uuid()})}save();document.querySelector('#dialog').close();slotDraft=null;render();toast('Saved')}
function requestConfirm(message,callback){pendingConfirm=callback;document.querySelector('#confirm-message').textContent=message;document.querySelector('#confirm-dialog').showModal()}
function deleteItem(kind,id){if(kind==='exam')kind='event';const map={course:db.courses,event:db.events,series:db.series,block:db.blocks},arr=map[kind];if(!arr)return;const found=arr.find(x=>x.id===id);if(!found)return;if(kind==='course'&&(db.events.some(x=>x.courseId===id)||db.series.some(x=>x.courseId===id)))return toast('This course still has linked items. Reassign or remove them first.');requestConfirm(kind==='series'?'Delete this recurring class for the entire semester? All scheduled dates and individual changes will be removed.':`Delete this ${kind}?`,()=>{arr.splice(arr.indexOf(found),1);if(kind==='series')db.exceptions=db.exceptions.filter(x=>x.seriesId!==id);save();render();toast('Deleted')})}
function action(el){const a=el.dataset.action,id=el.dataset.id,kind=el.dataset.kind;if(a==='undo-timetable'){const previous=db.undoTimetable;if(!previous)return toast('There is no timetable change to undo.');db.semester=previous.semester;db.series=previous.series;db.exceptions=previous.exceptions;db.blocks=previous.blocks;db.undoTimetable=null;undoingTimetable=true;if(!save())return;render();return toast('Last timetable change undone.')}if(a==='more-toggle'){const menu=document.querySelector('#mobile-more'),open=menu.hasAttribute('hidden');menu.toggleAttribute('hidden',!open);el.setAttribute('aria-expanded',String(open));return}if(a==='new'){slotDraft=null;return modal(kind)}if(a==='edit'){if(kind==='course')selectedCourse=id;return modal(kind,id)}if(a==='delete'){if(el.classList.contains('modal-delete'))document.querySelector('#dialog').close();return deleteItem(kind,id)}if(a==='occurrence'){if(id.includes('@')){selectedOccurrence=id;const [sid,date]=id.split('@'),s=db.series.find(x=>x.id===sid),ex=db.exceptions.find(x=>x.seriesId===sid&&x.date===date);if(!s)return;document.querySelector('#class-detail-title').textContent=ex?.title||s.title||course(s.courseId)?.name||'Class';document.querySelector('#class-detail-meta').textContent=`${DAY_NAMES[s.day]} · ${pretty(ex?.newDate||date,{weekday:'long',day:'numeric',month:'long'})} · ${ex?.start||s.start}–${ex?.end||s.end} · ${s.type||'Class'}`;document.querySelector('#class-detail-room').textContent=ex?.room||s.room||'Room not set';document.querySelector('#class-detail-dialog').showModal();return}return modal(db.events.find(x=>x.id===id)?.type==='Exam'?'exam':'event',id)}if(a==='class-edit'||a==='class-move'){document.querySelector('#class-detail-dialog').close();return modal('single',selectedOccurrence)}if(a==='class-delete'){const [sid]=selectedOccurrence.split('@');document.querySelector('#class-detail-dialog').close();return deleteItem('series',sid)}if(a==='close-class-dialog'){document.querySelector('#class-detail-dialog').close();return}if(a==='confirm-cancel'){pendingConfirm=null;document.querySelector('#confirm-dialog').close();return}if(a==='confirm-delete'){const cb=pendingConfirm;pendingConfirm=null;document.querySelector('#confirm-dialog').close();cb?.();return}if(a==='semester-save'){const s={...db.semester};document.querySelectorAll('[data-sem]').forEach(x=>s[x.dataset.sem]=x.type==='number'?Number(x.value):x.value);if(!s.start||!s.end||s.end<s.start)return toast('Semester end must be after its start.');if(db.series.some(x=>x.from<s.start||x.to>s.end))return toast('Update recurring class dates before shortening the semester.');db.semester=s;save();render();return toast('Semester saved')}if(a==='semester-view'){semesterView=el.dataset.value;return render()}if(a==='jump-week'){weekOffset=Number(el.dataset.offset);semesterView='week';return render()}if(a==='week-prev'){weekOffset--;return render()}if(a==='week-next'){weekOffset++;return render()}if(a==='week-now'){weekOffset=0;semesterView='week';return render()}if(a==='calendar-mode'){calendarMode=el.dataset.value;return render()}if(a==='cal-prev'||a==='cal-next'){const n=a==='cal-prev'?-1:1;if(calendarMode==='month')calendarDate.setMonth(calendarDate.getMonth()+n);else calendarDate.setDate(calendarDate.getDate()+n*(calendarMode==='week'?7:1));return render()}if(a==='cal-today'){calendarDate=new Date();return render()}if(a==='toggle-holidays'){const previous=db.showBerlinDates;db.showBerlinDates=previous===false;if(!save()){db.showBerlinDates=previous;return}render();return toast(db.showBerlinDates?'Holidays and breaks shown.':'Holidays and breaks hidden.')}if(a==='timer-start'){timerStart();return render()}if(a==='timer-pause'){timer.running=false;clearInterval(timer.interval);return render()}if(a==='timer-reset'){timer.running=false;clearInterval(timer.interval);timer.kind='study';timer.remaining=timerSettings.study*60;return render()}if(a==='timer-settings'){const study=Number(document.querySelector('#study-min').value),brk=Number(document.querySelector('#break-min').value);if(!Number.isFinite(study)||study<1||study>180||!Number.isFinite(brk)||brk<1||brk>60)return toast('Choose a valid study and break duration.');timerSettings={study,break:brk};timer.running=false;clearInterval(timer.interval);timer.kind='study';timer.remaining=study*60;return render()}if(a==='export')return exportBackup();if(a==='reset')return requestConfirm('Permanently delete all UniFlow data on this device?',()=>{localStorage.removeItem(KEY);db=starter();undoingTimetable=true;save();page='home';render();toast('Data reset')})}
function importBackup(file){const reader=new FileReader();reader.onload=()=>{try{const data=JSON.parse(reader.result);if(!data.semester||!Array.isArray(data.courses)||!Array.isArray(data.tasks)||!Array.isArray(data.series)||!Array.isArray(data.events))throw Error();requestConfirm('Importing this backup replaces current UniFlow data on this device.',()=>{db={...starter(),...data};db.exceptions||=[];db.blocks||=[];db.notes||=[];db.sessions||=[];db.undoTimetable=null;undoingTimetable=true;save();render();toast('Backup imported')})}catch{toast('This is not a valid UniFlow backup.')}};reader.readAsText(file)}
// Active pages use English directly; avoid the legacy German-string translation pass.
function translateText(value){return value}
function coursesPage(){return `${pageHeader('YOUR CAMPUS','Courses','Keep your courses, classes, and exams organized in one place.',btn('＋ Add course','new','course'))}<div class="course-grid">${db.courses.map(c=>`<article class="course-tile" style="--course:${esc(c.color||COLORS[0])}"><i></i><strong class="course-name">${esc(c.name)}</strong><div class="course-actions"><button data-action="edit" data-kind="course" data-id="${c.id}">Edit</button><button data-action="delete" data-kind="course" data-id="${c.id}">Delete</button></div></article>`).join('')}${!db.courses.length?`<div class="empty">No courses yet. <button class="link" data-action="new" data-kind="course">Add your first course</button></div>`:''}</div>`}
function semesterGrid(){const start=new Date(`${db.semester.start}T12:00:00`),end=new Date(`${db.semester.end}T12:00:00`),days=(Date.UTC(end.getFullYear(),end.getMonth(),end.getDate())-Date.UTC(start.getFullYear(),start.getMonth(),start.getDate()))/86400000,weeks=Math.ceil((days+1)/7);return `<div class="semester-weeks">${Array.from({length:weeks},(_,i)=>{const d=new Date(start);d.setDate(d.getDate()+i*7);const from=iso(d),through=from>db.semester.end?db.semester.end:addDays(from,6)>db.semester.end?db.semester.end:addDays(from,6),classes=classOccurrences(from,through).length,isBreak=db.blocks.some(b=>from<=b.to&&through>=b.from),offset=Math.round((weekStart(d)-weekStart(new Date()))/604800000);return `<button class="week-tile ${isBreak?'blocked':''}" data-action="jump-week" data-offset="${offset}"><small>WEEK ${i+1}</small><strong>${pretty(from)} – ${pretty(through)}</strong><span>${isBreak?'Break period':`${classes} classes`}</span></button>`}).join('')}</div>`}
function settingsPage(){return `${pageHeader('YOUR DATA','Data & backup','Your information stays in this browser.')}<section class="surface settings"><h2>Backup</h2><p>Export a JSON backup or restore a UniFlow backup from a file.</p>${btn('Export backup','export')}<label class="btn soft upload">Import backup<input type="file" id="import-file" accept="application/json"></label><h2>Local data</h2><p>Resetting removes courses, events, and recorded focus time from this browser.</p>${btn('Reset all data','reset','','danger-btn')}<p class="muted">Local storage · UniFlow v2</p></section>`}
function save(){const current=JSON.stringify(timetableState());if(!undoingTimetable&&current!==lastTimetableState)db.undoTimetable=JSON.parse(lastTimetableState);undoingTimetable=false;try{localStorage.setItem(KEY,JSON.stringify(db));lastTimetableState=JSON.stringify(timetableState());return true}catch(e){console.warn('UniFlow data could not be saved',e);toast('Storage is full or unavailable. Export a backup.');return false}}
let timetableDrag=null,ignoreOccurrenceClick=null;
document.addEventListener('pointerdown',e=>{const card=e.target.closest('.time-event');if(!card||e.button!==0||!card.dataset.id?.includes('@'))return;const rect=card.getBoundingClientRect();timetableDrag={id:card.dataset.id,pointerId:e.pointerId,x:e.clientX,y:e.clientY,offsetY:e.clientY-rect.top,card,moved:false,over:null}});
document.addEventListener('pointermove',e=>{if(!timetableDrag||e.pointerId!==timetableDrag.pointerId)return;const drag=timetableDrag;if(!drag.moved&&Math.hypot(e.clientX-drag.x,e.clientY-drag.y)<6)return;drag.moved=true;drag.card.classList.add('dragging');const day=document.elementFromPoint(e.clientX,e.clientY)?.closest('.time-day');if(drag.over&&drag.over!==day)drag.over.classList.remove('drag-over');drag.over=day;if(day)day.classList.add('drag-over');e.preventDefault()});
document.addEventListener('pointerup',e=>{if(!timetableDrag||e.pointerId!==timetableDrag.pointerId)return;const drag=timetableDrag;timetableDrag=null;drag.card.classList.remove('dragging');drag.over?.classList.remove('drag-over');if(!drag.moved)return;ignoreOccurrenceClick={id:drag.id,expires:Date.now()+700};const [seriesId,originalDate]=drag.id.split('@'),series=db.series.find(x=>x.id===seriesId),existing=db.exceptions.find(x=>x.seriesId===seriesId&&x.date===originalDate),day=document.elementFromPoint(e.clientX,e.clientY)?.closest('.time-day');if(!series||!day){toast('Drop the class inside a timetable day.');return}const targetDate=day.dataset.date;if(targetDate<db.semester.start||targetDate>db.semester.end){toast('Classes must stay within the semester dates.');return}const duration=timeMinutes(existing?.end||series.end)-timeMinutes(existing?.start||series.start),rect=day.getBoundingClientRect(),raw=TIMELINE_START+(e.clientY-drag.offsetY-rect.top),start=Math.max(TIMELINE_START,Math.min(TIMELINE_END-duration,Math.round(raw/15)*15)),format=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`,newStart=format(start),newEnd=format(start+duration);if(targetDate===(existing?.newDate||originalDate)&&newStart===(existing?.start||series.start)){return}const update={...(existing||{}),seriesId,date:originalDate,newDate:targetDate,start:newStart,end:newEnd,cancelled:false};if(existing){db.exceptions[db.exceptions.indexOf(existing)]=update}else db.exceptions.push(update);if(!save())return;render();toast('One class moved. The rest of the weekly series is unchanged.')});
document.addEventListener('click',e=>{const clickedOccurrence=e.target.closest('.time-event');if(ignoreOccurrenceClick&&Date.now()<ignoreOccurrenceClick.expires&&clickedOccurrence?.dataset.id===ignoreOccurrenceClick.id){ignoreOccurrenceClick=null;e.preventDefault();return}ignoreOccurrenceClick=null;const nav=e.target.closest('[data-page]');if(nav){setPage(nav.dataset.page);return}const control=e.target.closest('[data-action]');if(control){action(control);return}const day=e.target.closest('.time-day');if(!day||e.target.closest('.time-event'))return;const rect=day.getBoundingClientRect(),relative=e.clientY-rect.top+day.scrollTop,minute=Math.max(TIMELINE_START,Math.min(TIMELINE_END-30,Math.floor(relative/30)*30+TIMELINE_START)),hh=String(Math.floor(minute/60)).padStart(2,'0'),mm=String(minute%60).padStart(2,'0');slotDraft={day:(new Date(`${day.dataset.date}T12:00:00`).getDay()+6)%7,start:`${hh}:${mm}`,end:`${String(Math.floor((minute+60)/60)).padStart(2,'0')}:${String((minute+60)%60).padStart(2,'0')}`};modal('series')});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-action="occurrence"]')){e.preventDefault();action(e.target)}});
document.querySelector('#modal-form').addEventListener('submit',submitModal);document.querySelector('#modal-close').addEventListener('click',()=>document.querySelector('#dialog').close());document.querySelector('#modal-cancel').addEventListener('click',()=>document.querySelector('#dialog').close());
document.addEventListener('change',e=>{if(e.target.id==='focus-course'){const previous=db.focusCourseId;db.focusCourseId=e.target.value||'';if(!save()){db.focusCourseId=previous;return}toast('Course saved for your next focus session.')}if(e.target.id==='import-file'&&e.target.files[0])importBackup(e.target.files[0])});
document.querySelector('#class-detail-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});document.querySelector('#dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});document.querySelector('#confirm-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){pendingConfirm=null;e.currentTarget.close()}});document.querySelector('#confirm-dialog').addEventListener('cancel',()=>{pendingConfirm=null});render();
